return $input.all().map((item) => {
  let requiereAtencionHumana = false;

  for (const paso of item.json.intermediateSteps || []) {
    if (paso.action?.tool !== 'registrar_solicitud_reserva') {
      continue;
    }

    let resultado;

    try {
      resultado = typeof paso.observation === 'string'
        ? JSON.parse(paso.observation)
        : paso.observation;
    } catch {
      continue;
    }

    const resultados = Array.isArray(resultado)
      ? resultado
      : [resultado];

    for (const dato of resultados) {
      if (!dato || typeof dato !== 'object') continue;

      // Una consulta confirma el estado guardado.
      if (dato.encontrada === true && dato.solicitud?.estado) {
        requiereAtencionHumana =
          dato.solicitud.estado === 'requiere_atencion_humana';
      }

      // Una escritura exitosa confirma el estado resultante.
      if (dato.ok === true && dato.estado) {
        requiereAtencionHumana =
          dato.estado === 'requiere_atencion_humana';
      }
    }
  }
const idioma = $('Preparacion de datos').first().json.idioma;

const mensajeControlado = idioma === 'en'
  ? 'Your request has been flagged for the hostel manager’s attention. ' +
    'This does not confirm a booking or mean that a notification has been sent. ' +
    'No response timeframe is confirmed.'
  : 'Tu solicitud quedó marcada para atención del responsable del hostel. ' +
    'Esto no confirma una reserva ni implica que se haya enviado una notificación. ' +
    'No hay un plazo de respuesta confirmado.';

  return {
    json: {
      output: requiereAtencionHumana
        ? mensajeControlado
        : item.json.output
    }
  };
});
